package com.potionprep;

import static com.potionprep.Recipe.in;
import net.runelite.api.gameval.ItemID;

/** The recipe trees. Nodes are shared, so one super energy node feeds both Super energy and Stamina. */
final class Catalog
{
	private Catalog()
	{
	}

	static String lower(String s)
	{
		return s.isEmpty() ? s : Character.toLowerCase(s.charAt(0)) + s.substring(1);
	}

	static String plural(String s)
	{
		return s.endsWith("y") ? s.substring(0, s.length() - 1) + "ies" : s + "s";
	}

	// --- Tools and bases ---

	static final Node PESTLE = Node.item("Pestle and mortar", ItemID.PESTLE_AND_MORTAR, "General stores");
	static final Node VIAL = Node.item("Vial of water", ItemID.VIAL_WATER, "Fill vials at a sink or fountain, or the GE");
	static final Node COCONUT_MILK = Node.item("Coconut milk", ItemID.VIAL_COCONUT_MILK, "Smash a coconut and fill a vial, or the GE");

	// --- Herbs: grimy -> clean -> unf ---

	static final class Herb
	{
		final Node grimy;
		final Node clean;
		final Node unf;

		Herb(String name, int grimyId, int cleanId, int unfId, int cleanLevel, int unfLevel)
		{
			grimy = Node.item("Grimy " + lower(name), grimyId, "Farming, drops, or the GE");
			clean = Node.item(name, cleanId, "Farming, drops, or the GE").madeBy(Recipe.clean(grimy, cleanLevel));
			// In game the unf drops "leaf"/"weed": Guam potion (unf), Ranarr potion (unf).
			String shortName = name.replace(" leaf", "").replace("Ranarr weed", "Ranarr");
			unf = Node.item(shortName + " potion (unf)", unfId, null)
				.madeBy(Recipe.mix(unfLevel, 1, "Make %d " + lower(shortName) + " (unf)", in(clean, 1), in(VIAL, 1)));
		}
	}

	static final Herb GUAM = new Herb("Guam leaf", ItemID.UNIDENTIFIED_GUAM, ItemID.GUAM_LEAF, ItemID.GUAMVIAL, 3, 3);
	static final Herb MARRENTILL = new Herb("Marrentill", ItemID.UNIDENTIFIED_MARENTILL, ItemID.MARENTILL, ItemID.MARRENTILLVIAL, 5, 5);
	static final Herb TARROMIN = new Herb("Tarromin", ItemID.UNIDENTIFIED_TARROMIN, ItemID.TARROMIN, ItemID.TARROMINVIAL, 11, 12);
	static final Herb HARRALANDER = new Herb("Harralander", ItemID.UNIDENTIFIED_HARRALANDER, ItemID.HARRALANDER, ItemID.HARRALANDERVIAL, 20, 22);
	static final Herb RANARR = new Herb("Ranarr weed", ItemID.UNIDENTIFIED_RANARR, ItemID.RANARR_WEED, ItemID.RANARRVIAL, 25, 30);
	static final Herb TOADFLAX = new Herb("Toadflax", ItemID.UNIDENTIFIED_TOADFLAX, ItemID.TOADFLAX, ItemID.TOADFLAXVIAL, 30, 34);
	static final Herb IRIT = new Herb("Irit leaf", ItemID.UNIDENTIFIED_IRIT, ItemID.IRIT_LEAF, ItemID.IRITVIAL, 40, 45);
	static final Herb AVANTOE = new Herb("Avantoe", ItemID.UNIDENTIFIED_AVANTOE, ItemID.AVANTOE, ItemID.AVANTOEVIAL, 48, 50);
	static final Herb KWUARM = new Herb("Kwuarm", ItemID.UNIDENTIFIED_KWUARM, ItemID.KWUARM, ItemID.KWUARMVIAL, 54, 55);
	static final Herb SNAPDRAGON = new Herb("Snapdragon", ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.SNAPDRAGON, ItemID.SNAPDRAGONVIAL, 59, 63);
	static final Herb CADANTINE = new Herb("Cadantine", ItemID.UNIDENTIFIED_CADANTINE, ItemID.CADANTINE, ItemID.CADANTINEVIAL, 65, 66);
	static final Herb LANTADYME = new Herb("Lantadyme", ItemID.UNIDENTIFIED_LANTADYME, ItemID.LANTADYME, ItemID.LANTADYMEVIAL, 67, 69);
	static final Herb DWARF_WEED = new Herb("Dwarf weed", ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.DWARF_WEED, ItemID.DWARFWEEDVIAL, 70, 72);
	static final Herb TORSTOL = new Herb("Torstol", ItemID.UNIDENTIFIED_TORSTOL, ItemID.TORSTOL, ItemID.TORSTOLVIAL, 75, 78);

	// --- Secondaries ---

	private static Node crushed(String name, int id, String rawName, int rawId, int yield, String source)
	{
		Node raw = Node.item(rawName, rawId, source);
		return Node.item(name, id, source).madeBy(Recipe.crush(raw, yield, PESTLE));
	}

	static final Node EYE_OF_NEWT = Node.item("Eye of newt", ItemID.EYE_OF_NEWT, "Herblore shops or the GE");
	static final Node UNICORN_HORN_DUST = crushed("Unicorn horn dust", ItemID.UNICORN_HORN_DUST, "Unicorn horn", ItemID.UNICORN_HORN, 1, "Unicorns, or the GE");
	static final Node LIMPWURT_ROOT = Node.item("Limpwurt root", ItemID.LIMPWURT_ROOT, "Hill giants, farming, or the GE");
	static final Node RED_SPIDERS_EGGS = Node.item("Red spiders' eggs", ItemID.RED_SPIDERS_EGGS, "Red spiders, spawns, or the GE");
	static final Node CHOCOLATE_DUST = crushed("Chocolate dust", ItemID.CHOCOLATE_DUST, "Chocolate bar", ItemID.CHOCOLATE_BAR, 1, "Food shops or the GE");
	static final Node WHITE_BERRIES = Node.item("White berries", ItemID.WHITE_BERRIES, "Whiteberry bush, or the GE");
	static final Node TOADS_LEGS = Node.item("Toad's legs", ItemID.TOADS_LEGS, "Gnome shops or the GE");
	static final Node GOAT_HORN_DUST = crushed("Goat horn dust", ItemID.GROUND_DESERT_GOAT_HORN, "Desert goat horn", ItemID.DESERT_GOAT_HORN, 1, "Desert goats, or the GE");
	static final Node SNAPE_GRASS = Node.item("Snape grass", ItemID.SNAPE_GRASS, "Spawns, farming, or the GE");
	static final Node MORT_MYRE_FUNGUS = Node.item("Mort myre fungus", ItemID.MORTMYREMUSHROOM, "Cast Bloom in Mort Myre, or the GE");
	static final Node KEBBIT_TEETH_DUST = crushed("Kebbit teeth dust", ItemID.HUNTINGBEAST_SABRETEETH_DUST, "Kebbit teeth", ItemID.HUNTINGBEAST_SABRETEETH, 1, "Sabre-toothed kebbits, or the GE");
	static final Node DRAGON_SCALE_DUST = crushed("Dragon scale dust", ItemID.DRAGON_SCALE_DUST, "Blue dragon scale", ItemID.BLUE_DRAGON_SCALE, 1, "Blue dragons, or the GE");
	static final Node WINE_OF_ZAMORAK = Node.item("Wine of Zamorak", ItemID.WINE_OF_ZAMORAK, "Telegrab at the Chaos Temple, or the GE");
	static final Node POTATO_CACTUS = Node.item("Potato cactus", ItemID.CACTUS_POTATO, "Kalphite Lair spawns, or the GE");
	static final Node JANGERBERRIES = Node.item("Jangerberries", ItemID.JANGERBERRIES, "Jangerberry bush, or the GE");
	static final Node CRUSHED_NEST = crushed("Crushed nest", ItemID.CRUSHED_BIRD_NEST, "Bird nest", ItemID.BIRD_NEST_EMPTY, 1, "Woodcutting, birdhouses, or the GE");
	static final Node AMYLASE = Node.item("Amylase crystal", ItemID.AMYLASE, "Grace's shop (marks of grace), or the GE");
	// Crushing a lava scale gives 3-6 shards; plan with the minimum.
	static final Node LAVA_SHARD = crushed("Lava scale shard", ItemID.LAVA_SHARD, "Lava scale", ItemID.LAVA_SCALE, 3, "Lava dragons, or the GE");
	static final Node CRUSHED_SUPERIOR_BONES = crushed("Crushed superior dragon bones", ItemID.CRUSHED_DRAGON_BONES, "Superior dragon bones", ItemID.DRAGON_BONES_SUPERIOR, 1, "Wyrms, drakes, hydras, or the GE");
	static final Node MAGIC_ROOTS = Node.item("Magic roots", ItemID.MAGIC_ROOTS, "Magic tree farming, or the GE");
	static final Node ZULRAH_SCALES = Node.item("Zulrah's scales", ItemID.SNAKEBOSS_SCALE, "Zulrah, or the GE");

	// --- Potions ---

	/** unf + secondary = one 3-dose potion. */
	private static Node standard(String name, int level, Herb herb, Node secondary, int d1, int d2, int d3, int d4)
	{
		return Node.dosed(name, d1, d2, d3, d4)
			.madeBy(Recipe.mix(level, 3, "Mix %d " + plural(lower(name)), in(herb.unf, 1), in(secondary, 1)));
	}

	static final Node ATTACK = standard("Attack potion", 3, GUAM, EYE_OF_NEWT, ItemID._1DOSE1ATTACK, ItemID._2DOSE1ATTACK, ItemID._3DOSE1ATTACK, ItemID._4DOSE1ATTACK);
	static final Node ANTIPOISON = standard("Antipoison", 5, MARRENTILL, UNICORN_HORN_DUST, ItemID._1DOSEANTIPOISON, ItemID._2DOSEANTIPOISON, ItemID._3DOSEANTIPOISON, ItemID._4DOSEANTIPOISON);
	static final Node STRENGTH = standard("Strength potion", 12, TARROMIN, LIMPWURT_ROOT, ItemID._1DOSE1STRENGTH, ItemID._2DOSE1STRENGTH, ItemID._3DOSE1STRENGTH, ItemID.STRENGTH4);
	static final Node RESTORE = standard("Restore potion", 22, HARRALANDER, RED_SPIDERS_EGGS, ItemID._1DOSESTATRESTORE, ItemID._2DOSESTATRESTORE, ItemID._3DOSESTATRESTORE, ItemID._4DOSESTATRESTORE);
	static final Node ENERGY = standard("Energy potion", 26, HARRALANDER, CHOCOLATE_DUST, ItemID._1DOSE1ENERGY, ItemID._2DOSE1ENERGY, ItemID._3DOSE1ENERGY, ItemID._4DOSE1ENERGY);
	static final Node DEFENCE = standard("Defence potion", 30, RANARR, WHITE_BERRIES, ItemID._1DOSE1DEFENSE, ItemID._2DOSE1DEFENSE, ItemID._3DOSE1DEFENSE, ItemID._4DOSE1DEFENSE);
	static final Node AGILITY = standard("Agility potion", 34, TOADFLAX, TOADS_LEGS, ItemID._1DOSE1AGILITY, ItemID._2DOSE1AGILITY, ItemID._3DOSE1AGILITY, ItemID._4DOSE1AGILITY);
	static final Node COMBAT = standard("Combat potion", 36, HARRALANDER, GOAT_HORN_DUST, ItemID._1DOSECOMBAT, ItemID._2DOSECOMBAT, ItemID._3DOSECOMBAT, ItemID._4DOSECOMBAT);
	static final Node PRAYER = standard("Prayer potion", 38, RANARR, SNAPE_GRASS, ItemID._1DOSEPRAYERRESTORE, ItemID._2DOSEPRAYERRESTORE, ItemID._3DOSEPRAYERRESTORE, ItemID._4DOSEPRAYERRESTORE);
	static final Node SUPER_ATTACK = standard("Super attack", 45, IRIT, EYE_OF_NEWT, ItemID._1DOSE2ATTACK, ItemID._2DOSE2ATTACK, ItemID._3DOSE2ATTACK, ItemID._4DOSE2ATTACK);
	static final Node SUPERANTIPOISON = standard("Superantipoison", 48, IRIT, UNICORN_HORN_DUST, ItemID._1DOSE2ANTIPOISON, ItemID._2DOSE2ANTIPOISON, ItemID._3DOSE2ANTIPOISON, ItemID._4DOSE2ANTIPOISON);
	static final Node FISHING = standard("Fishing potion", 50, AVANTOE, SNAPE_GRASS, ItemID._1DOSEFISHERSPOTION, ItemID._2DOSEFISHERSPOTION, ItemID._3DOSEFISHERSPOTION, ItemID._4DOSEFISHERSPOTION);
	static final Node SUPER_ENERGY = standard("Super energy", 52, AVANTOE, MORT_MYRE_FUNGUS, ItemID._1DOSE2ENERGY, ItemID._2DOSE2ENERGY, ItemID._3DOSE2ENERGY, ItemID._4DOSE2ENERGY);
	static final Node HUNTER = standard("Hunter potion", 53, AVANTOE, KEBBIT_TEETH_DUST, ItemID._1DOSEHUNTING, ItemID._2DOSEHUNTING, ItemID._3DOSEHUNTING, ItemID._4DOSEHUNTING);
	static final Node SUPER_STRENGTH = standard("Super strength", 55, KWUARM, LIMPWURT_ROOT, ItemID._1DOSE2STRENGTH, ItemID._2DOSE2STRENGTH, ItemID._3DOSE2STRENGTH, ItemID._4DOSE2STRENGTH);
	static final Node WEAPON_POISON = Node.item("Weapon poison", ItemID.WEAPON_POISON, null)
		.madeBy(Recipe.mix(60, 1, "Mix %d weapon poison", in(KWUARM.unf, 1), in(DRAGON_SCALE_DUST, 1)));
	static final Node SUPER_RESTORE = standard("Super restore", 63, SNAPDRAGON, RED_SPIDERS_EGGS, ItemID._1DOSE2RESTORE, ItemID._2DOSE2RESTORE, ItemID._3DOSE2RESTORE, ItemID._4DOSE2RESTORE);
	static final Node SUPER_DEFENCE = standard("Super defence", 66, CADANTINE, WHITE_BERRIES, ItemID._1DOSE2DEFENSE, ItemID._2DOSE2DEFENSE, ItemID._3DOSE2DEFENSE, ItemID._4DOSE2DEFENSE);
	static final Node ANTIFIRE = standard("Antifire potion", 69, LANTADYME, DRAGON_SCALE_DUST, ItemID._1DOSE1ANTIDRAGON, ItemID._2DOSE1ANTIDRAGON, ItemID._3DOSE1ANTIDRAGON, ItemID._4DOSE1ANTIDRAGON);
	static final Node RANGING = standard("Ranging potion", 72, DWARF_WEED, WINE_OF_ZAMORAK, ItemID._1DOSERANGERSPOTION, ItemID._2DOSERANGERSPOTION, ItemID._3DOSERANGERSPOTION, ItemID._4DOSERANGERSPOTION);
	static final Node MAGIC = standard("Magic potion", 76, LANTADYME, POTATO_CACTUS, ItemID._1DOSE1MAGIC, ItemID._2DOSE1MAGIC, ItemID._3DOSE1MAGIC, ItemID._4DOSE1MAGIC);
	static final Node ZAMORAK_BREW = standard("Zamorak brew", 78, TORSTOL, JANGERBERRIES, ItemID._1DOSEPOTIONOFZAMORAK, ItemID._2DOSEPOTIONOFZAMORAK, ItemID._3DOSEPOTIONOFZAMORAK, ItemID._4DOSEPOTIONOFZAMORAK);
	static final Node SARADOMIN_BREW = standard("Saradomin brew", 81, TOADFLAX, CRUSHED_NEST, ItemID._1DOSEPOTIONOFSARADOMIN, ItemID._2DOSEPOTIONOFSARADOMIN, ItemID._3DOSEPOTIONOFSARADOMIN, ItemID._4DOSEPOTIONOFSARADOMIN);

	// --- Multi-step potions ---

	/** One amylase crystal per dose of super energy. */
	static final Node STAMINA = Node.dosed("Stamina potion", ItemID._1DOSESTAMINA, ItemID._2DOSESTAMINA, ItemID._3DOSESTAMINA, ItemID._4DOSESTAMINA)
		.madeBy(Recipe.mix(77, 1, "Add amylase to %d doses", in(SUPER_ENERGY, 1), in(AMYLASE, 1)));

	/** One lava scale shard per dose of antifire. */
	static final Node EXTENDED_ANTIFIRE = Node.dosed("Extended antifire", ItemID._1DOSE2ANTIDRAGON, ItemID._2DOSE2ANTIDRAGON, ItemID._3DOSE2ANTIDRAGON, ItemID._4DOSE2ANTIDRAGON)
		.madeBy(Recipe.mix(84, 1, "Add shards to %d doses", in(ANTIFIRE, 1), in(LAVA_SHARD, 1)));

	/** Crushed superior dragon bones + antifire(4) = super antifire(4). */
	static final Node SUPER_ANTIFIRE = Node.dosed("Super antifire", ItemID._1DOSE3ANTIDRAGON, ItemID._2DOSE3ANTIDRAGON, ItemID._3DOSE3ANTIDRAGON, ItemID._4DOSE3ANTIDRAGON)
		.madeBy(Recipe.mix(92, 4, "Mix %d super antifires", in(ANTIFIRE, 4), in(CRUSHED_SUPERIOR_BONES, 1)));

	static final Node EXTENDED_SUPER_ANTIFIRE = Node.dosed("Extended super antifire", ItemID._1DOSE4ANTIDRAGON, ItemID._2DOSE4ANTIDRAGON, ItemID._3DOSE4ANTIDRAGON, ItemID._4DOSE4ANTIDRAGON)
		.madeBy(Recipe.mix(98, 1, "Add shards to %d doses", in(SUPER_ANTIFIRE, 1), in(LAVA_SHARD, 1)));

	/** Torstol + super attack(4) + super strength(4) + super defence(4). */
	static final Node SUPER_COMBAT = Node.dosed("Super combat", ItemID._1DOSE2COMBAT, ItemID._2DOSE2COMBAT, ItemID._3DOSE2COMBAT, ItemID._4DOSE2COMBAT)
		.madeBy(Recipe.mix(90, 4, "Mix %d super combats",
			in(SUPER_ATTACK, 4), in(SUPER_STRENGTH, 4), in(SUPER_DEFENCE, 4), in(TORSTOL.clean, 1)));

	static final Node ANTIDOTE_PP_UNF = Node.item("Antidote++ (unf)", ItemID.UNFINISHED_ANTIDOTE__, null)
		.madeBy(Recipe.mix(79, 1, "Make %d antidote++ (unf)", in(IRIT.clean, 1), in(COCONUT_MILK, 1)));

	static final Node ANTIDOTE_PP = Node.dosed("Antidote++", ItemID.ANTIDOTE__1, ItemID.ANTIDOTE__2, ItemID.ANTIDOTE__3, ItemID.ANTIDOTE__4)
		.madeBy(Recipe.mix(79, 3, "Mix %d antidote++", in(ANTIDOTE_PP_UNF, 1), in(MAGIC_ROOTS, 1)));

	/** Five Zulrah's scales per dose of antidote++. */
	static final Node ANTI_VENOM = Node.dosed("Anti-venom", ItemID.ANTIVENOM1, ItemID.ANTIVENOM2, ItemID.ANTIVENOM3, ItemID.ANTIVENOM4)
		.madeBy(Recipe.mix(87, 1, "Add scales to %d doses", in(ANTIDOTE_PP, 1), in(ZULRAH_SCALES, 5)));

	static final Node ANTI_VENOM_PLUS = Node.dosed("Anti-venom+", ItemID.ANTIVENOM_1, ItemID.ANTIVENOM_2, ItemID.ANTIVENOM_3, ItemID.ANTIVENOM_4)
		.madeBy(Recipe.mix(94, 4, "Mix %d anti-venom+", in(ANTI_VENOM, 4), in(TORSTOL.clean, 1)));
}

package com.potionprep;

import java.util.Map;
import lombok.Getter;

/**
 * One item in a recipe tree. Potions are "dosed": counted in doses across
 * their 1-4 dose variants, since doses can be decanted freely.
 */
@Getter
public final class Node
{
	private final String name;
	/** Main item id; for dosed items the 4-dose id. */
	private final int id;
	/** Ids indexed by dose - 1, or null for non-dosed items. */
	private final int[] doseIds;
	/** Where to get it when it cannot be made, or null. */
	private final String source;
	private Recipe recipe;

	private Node(String name, int id, int[] doseIds, String source)
	{
		this.name = name;
		this.id = id;
		this.doseIds = doseIds;
		this.source = source;
	}

	static Node item(String name, int id, String source)
	{
		return new Node(name, id, null, source);
	}

	static Node dosed(String name, int d1, int d2, int d3, int d4)
	{
		return new Node(name, d4, new int[]{d1, d2, d3, d4}, null);
	}

	Node madeBy(Recipe recipe)
	{
		this.recipe = recipe;
		return this;
	}

	public boolean isDosed()
	{
		return doseIds != null;
	}

	/** Ids for this item's bank row: (1) (2) (3) (4) left to right for potions. */
	public int[] rowIds()
	{
		return isDosed() ? doseIds.clone() : new int[]{id};
	}

	/** Units held: item count, or total doses. */
	public int count(Map<Integer, Integer> counts)
	{
		if (!isDosed())
		{
			return counts.getOrDefault(id, 0);
		}
		int doses = 0;
		for (int d = 0; d < 4; d++)
		{
			doses += (d + 1) * counts.getOrDefault(doseIds[d], 0);
		}
		return doses;
	}
}

package com.potionprep;

import lombok.Getter;

/** The potions offered in the panel, each the root of a recipe tree. */
@Getter
public enum Potion
{
	ATTACK(Catalog.ATTACK),
	ANTIPOISON(Catalog.ANTIPOISON),
	STRENGTH(Catalog.STRENGTH),
	RESTORE(Catalog.RESTORE),
	ENERGY(Catalog.ENERGY),
	DEFENCE(Catalog.DEFENCE),
	AGILITY(Catalog.AGILITY),
	COMBAT(Catalog.COMBAT),
	PRAYER(Catalog.PRAYER),
	SUPER_ATTACK(Catalog.SUPER_ATTACK),
	SUPERANTIPOISON(Catalog.SUPERANTIPOISON),
	FISHING(Catalog.FISHING),
	SUPER_ENERGY(Catalog.SUPER_ENERGY),
	HUNTER(Catalog.HUNTER),
	SUPER_STRENGTH(Catalog.SUPER_STRENGTH),
	WEAPON_POISON(Catalog.WEAPON_POISON),
	SUPER_RESTORE(Catalog.SUPER_RESTORE),
	SUPER_DEFENCE(Catalog.SUPER_DEFENCE),
	ANTIFIRE(Catalog.ANTIFIRE),
	RANGING(Catalog.RANGING),
	MAGIC(Catalog.MAGIC),
	STAMINA(Catalog.STAMINA),
	ZAMORAK_BREW(Catalog.ZAMORAK_BREW),
	ANTIDOTE_PLUS_PLUS(Catalog.ANTIDOTE_PP),
	SARADOMIN_BREW(Catalog.SARADOMIN_BREW),
	EXTENDED_ANTIFIRE(Catalog.EXTENDED_ANTIFIRE),
	ANTI_VENOM(Catalog.ANTI_VENOM),
	SUPER_COMBAT(Catalog.SUPER_COMBAT),
	SUPER_ANTIFIRE(Catalog.SUPER_ANTIFIRE),
	ANTI_VENOM_PLUS(Catalog.ANTI_VENOM_PLUS),
	EXTENDED_SUPER_ANTIFIRE(Catalog.EXTENDED_SUPER_ANTIFIRE);

	private final Node product;

	Potion(Node product)
	{
		this.product = product;
	}

	public String getName()
	{
		return product.getName();
	}

	public int getLevel()
	{
		return product.getRecipe().getLevel();
	}

	/**
	 * Final crafts per displayed potion. Dose-by-dose recipes (stamina,
	 * extended antifire, anti-venom) are shown as 4-dose potions.
	 */
	public int craftsPerPotion()
	{
		return product.isDosed() && product.getRecipe().getYield() == 1 ? 4 : 1;
	}

	/** Potions you can make from this many final crafts. */
	public int toPotions(int crafts)
	{
		return crafts / craftsPerPotion();
	}

	/** What one displayed potion is, e.g. "Stamina potion(4)", "Prayer potion(3)". */
	public String potionName()
	{
		if (!product.isDosed())
		{
			return getName();
		}
		return getName() + (product.getRecipe().getYield() == 3 ? "(3)" : "(4)");
	}

	@Override
	public String toString()
	{
		return getName() + " (" + getLevel() + ")";
	}
}

package com.potionprep;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Clickable grid of potion icons. Each tile shows how many you can make
 * with what you have, or the Herblore level you still need.
 */
class PotionGrid extends JPanel
{
	private static final int COLUMNS = 5;
	private static final Color GOOD = new Color(0x5FBF5F);
	private static final Color BAD = new Color(0xE05A5A);

	private final Map<Potion, Tile> tiles = new EnumMap<>(Potion.class);
	private final Consumer<Potion> onSelect;
	private Potion selected;
	private String filter = "";

	PotionGrid(ItemManager itemManager, Consumer<Potion> onSelect)
	{
		super(new GridLayout(0, COLUMNS, 3, 3));
		this.onSelect = onSelect;
		setOpaque(false);
		for (Potion p : Potion.values())
		{
			Tile t = new Tile(p);
			itemManager.getImage(p.getProduct().getId()).addTo(t.icon);
			tiles.put(p, t);
		}
		layoutTiles();
	}

	void setFilter(String text)
	{
		String f = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
		if (!f.equals(filter))
		{
			filter = f;
			layoutTiles();
		}
	}

	/** First tile matching the filter, for Enter in the search box. */
	Potion firstVisible()
	{
		for (Potion p : Potion.values())
		{
			if (matches(p))
			{
				return p;
			}
		}
		return null;
	}

	void setSelected(Potion potion)
	{
		selected = potion;
		tiles.values().forEach(Tile::paintState);
	}

	void setStats(Map<Potion, Integer> makeable, int herbloreLevel)
	{
		for (Tile t : tiles.values())
		{
			int lvl = t.potion.getLevel();
			if (herbloreLevel > 0 && herbloreLevel < lvl)
			{
				t.count.setText("Lv " + lvl);
				t.count.setForeground(BAD);
				t.makeable = -1;
			}
			else
			{
				int n = t.potion.toPotions(makeable.getOrDefault(t.potion, 0));
				t.count.setText(QuantityFormatter.quantityToStackSize(n));
				t.count.setForeground(n > 0 ? GOOD : ColorScheme.MEDIUM_GRAY_COLOR);
				t.makeable = n;
			}
			t.updateTooltip();
		}
	}

	private boolean matches(Potion p)
	{
		return filter.isEmpty() || p.getName().toLowerCase(Locale.ROOT).contains(filter);
	}

	private void layoutTiles()
	{
		removeAll();
		for (Potion p : Potion.values())
		{
			if (matches(p))
			{
				add(tiles.get(p));
			}
		}
		revalidate();
		repaint();
	}

	private class Tile extends JPanel
	{
		final Potion potion;
		final JLabel icon = new JLabel();
		final JLabel count = new JLabel(" ");
		int makeable;
		boolean hover;

		Tile(Potion potion)
		{
			super(new BorderLayout());
			this.potion = potion;
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			count.setHorizontalAlignment(SwingConstants.CENTER);
			count.setFont(FontManager.getRunescapeSmallFont());
			count.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			add(icon, BorderLayout.CENTER);
			add(count, BorderLayout.SOUTH);
			updateTooltip();
			paintState();

			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					onSelect.accept(potion);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					paintState();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					paintState();
				}
			});
		}

		void updateTooltip()
		{
			String line = makeable < 0 ? "Needs " + potion.getLevel() + " Herblore"
				: "Level " + potion.getLevel() + " &middot; can make " + makeable + " &times; " + potion.potionName();
			setToolTipText("<html>" + potion.getName() + "<br>" + line + "</html>");
		}

		void paintState()
		{
			boolean sel = potion == selected;
			setBackground(sel ? ColorScheme.DARK_GRAY_HOVER_COLOR
				: hover ? ColorScheme.MEDIUM_GRAY_COLOR
				: ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createLineBorder(sel ? ColorScheme.BRAND_ORANGE : getBackground(), 1));
		}
	}
}

package com.potionprep;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.Value;

/**
 * Walks a potion's recipe tree against what the player holds: how many can
 * be made, which prep steps (clean, unf, crush, intermediate potions) get
 * there, and what is short. No client access, so it is unit-testable.
 */
@Getter
public final class PotionPlan
{
	@Value
	public static class Row
	{
		String name;
		int itemId;
		int have;
		boolean doses;
	}

	public enum Severity
	{
		ACTION,
		WARNING
	}

	@Value
	public static class Step
	{
		Severity severity;
		String text;
		/** Extra detail for the tooltip, or null. */
		String hint;
	}

	private static final int MAX_UNITS = 1_000_000;

	private final Potion potion;
	private final List<Row> rows;
	private final List<Step> steps;
	/** Final crafts possible once all prep is done. */
	private final int makeable;
	/** Final crafts possible with no prep at all. */
	private final int makeableNow;

	private PotionPlan(Potion potion, List<Row> rows, List<Step> steps, int makeable, int makeableNow)
	{
		this.potion = potion;
		this.rows = Collections.unmodifiableList(rows);
		this.steps = Collections.unmodifiableList(steps);
		this.makeable = makeable;
		this.makeableNow = makeableNow;
	}

	/**
	 * Every ingredient in the tree, in the order you work through it: each
	 * input's own chain first (grimy, clean, vial, unf, raw, secondary...),
	 * tools last. The finished potion itself is not included.
	 */
	static List<Node> ingredients(Potion potion)
	{
		Set<Node> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		List<Node> out = new ArrayList<>();
		List<Node> tools = new ArrayList<>();
		for (Recipe.Input in : potion.getProduct().getRecipe().getInputs())
		{
			visit(in.getNode(), seen, out, tools);
		}
		for (Node t : tools)
		{
			if (seen.add(t))
			{
				out.add(t);
			}
		}
		return out;
	}

	private static void visit(Node node, Set<Node> seen, List<Node> out, List<Node> tools)
	{
		if (seen.contains(node))
		{
			return;
		}
		Recipe r = node.getRecipe();
		if (r != null)
		{
			for (Recipe.Input in : r.getInputs())
			{
				visit(in.getNode(), seen, out, tools);
			}
			if (r.getTool() != null && !tools.contains(r.getTool()))
			{
				tools.add(r.getTool());
			}
		}
		if (seen.add(node))
		{
			out.add(node);
		}
	}

	static final int BANK_COLUMNS = 8;

	/**
	 * The bank layout: one row per task, in the order you do them. Each row
	 * holds everything that task needs (inputs, then any tool) but not what
	 * it makes; an output only reappears as an input on a later row. Potions
	 * fill their slots with doses (1)-(4). Rows wider than the bank wrap.
	 *
	 * Superantipoison: [grimy irit] / [irit, vial] / [unicorn horn, pestle]
	 * / [irit (unf), unicorn horn dust].
	 */
	public static List<int[]> layoutRows(Potion potion)
	{
		Set<Node> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		List<int[]> rows = new ArrayList<>();
		Recipe fin = potion.getProduct().getRecipe();
		for (Recipe.Input in : fin.getInputs())
		{
			addTasks(in.getNode(), seen, rows);
		}
		addRow(rows, taskIds(fin));
		return rows;
	}

	private static void addTasks(Node node, Set<Node> seen, List<int[]> rows)
	{
		Recipe r = node.getRecipe();
		if (r == null || !seen.add(node))
		{
			return;
		}
		for (Recipe.Input in : r.getInputs())
		{
			addTasks(in.getNode(), seen, rows);
		}
		addRow(rows, taskIds(r));
	}

	private static List<Integer> taskIds(Recipe r)
	{
		List<Integer> ids = new ArrayList<>();
		for (Recipe.Input in : r.getInputs())
		{
			for (int id : in.getNode().rowIds())
			{
				ids.add(id);
			}
		}
		if (r.getTool() != null)
		{
			ids.add(r.getTool().getId());
		}
		return ids;
	}

	private static void addRow(List<int[]> rows, List<Integer> ids)
	{
		for (int i = 0; i < ids.size(); i += BANK_COLUMNS)
		{
			List<Integer> chunk = ids.subList(i, Math.min(ids.size(), i + BANK_COLUMNS));
			rows.add(chunk.stream().mapToInt(Integer::intValue).toArray());
		}
	}

	/** Every distinct item id in the layout. */
	public static List<Integer> layoutItems(Potion potion)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (int[] row : layoutRows(potion))
		{
			for (int id : row)
			{
				ids.add(id);
			}
		}
		return new ArrayList<>(ids);
	}

	/**
	 * @param counts        item id to quantity, bank plus inventory
	 * @param herbloreLevel real Herblore level, or 0 if unknown
	 */
	public static PotionPlan compute(Potion potion, Map<Integer, Integer> counts, int herbloreLevel)
	{
		Node product = potion.getProduct();
		Recipe fin = product.getRecipe();
		List<Node> nodes = ingredients(potion);

		Map<Node, Integer> base = new IdentityHashMap<>();
		List<Row> rows = new ArrayList<>();
		for (Node n : nodes)
		{
			// Cap so the simulation's arithmetic can never overflow.
			int have = Math.min(n.count(counts), MAX_UNITS);
			base.put(n, have);
			rows.add(new Row(n.getName(), n.getId(), have, n.isDosed()));
		}

		List<Step> steps = new ArrayList<>();
		if (herbloreLevel > 0 && herbloreLevel < fin.getLevel())
		{
			steps.add(new Step(Severity.WARNING, "Needs " + fin.getLevel() + " Herblore", "You have " + herbloreLevel));
			return new PotionPlan(potion, rows, steps, 0, 0);
		}

		// No input yields more than 3 per craft, so this comfortably bounds the search.
		long sum = 1;
		for (int v : base.values())
		{
			sum += (long) v * 3;
		}
		int bound = (int) Math.min(sum, MAX_UNITS * 3L);

		int makeable = maxCrafts(fin, base, herbloreLevel, true, bound);
		int makeableNow = maxCrafts(fin, base, herbloreLevel, false, bound);

		// Prep steps that get you to `makeable`, in the order you would do them.
		Ctx run = new Ctx(base, herbloreLevel, true);
		run.makeFinal(fin, makeable);
		for (Map.Entry<Recipe, Integer> e : run.crafts.entrySet())
		{
			steps.add(new Step(Severity.ACTION, String.format(Locale.US, e.getKey().getStepFormat().replace("%d", "%,d"), e.getValue()), null));
		}

		// What stops you making more? Aim for what your best-stocked input
		// would allow, and list what that needs.
		int target = 0;
		for (Recipe.Input in : fin.getInputs())
		{
			target = Math.max(target, maxForInput(in, base, herbloreLevel, bound));
		}
		Map<String, String> warnings = new LinkedHashMap<>();
		if (target > makeable)
		{
			Ctx want = new Ctx(base, herbloreLevel, true);
			want.makeFinal(fin, target);
			for (Map.Entry<Node, Integer> e : want.shortfalls.entrySet())
			{
				Node n = e.getKey();
				Map<Node, Integer> group = want.groups.get(n);
				if (group != null)
				{
					StringBuilder sb = new StringBuilder(n.getName() + ": short ");
					String sep = "";
					for (Map.Entry<Node, Integer> g : group.entrySet())
					{
						sb.append(sep).append(qty(g.getKey(), g.getValue()));
						sep = ", ";
					}
					warnings.put(sb.toString(), null);
				}
				else
				{
					warnings.put("Short " + qty(n, e.getValue()), n.getSource());
				}
			}
			want.blocked.forEach(b -> warnings.putIfAbsent(b, null));
		}
		run.blocked.forEach(b -> warnings.putIfAbsent(b, null));

		warnings.forEach((text, hint) -> steps.add(new Step(Severity.WARNING, text, hint)));
		if (makeable == 0 && warnings.isEmpty())
		{
			steps.add(new Step(Severity.WARNING, "Nothing found. Open your bank.", null));
		}

		return new PotionPlan(potion, rows, steps, makeable, makeableNow);
	}

	/** Just the "can make" number, for the potion grid. */
	public static int makeable(Potion potion, Map<Integer, Integer> counts, int herbloreLevel)
	{
		Recipe fin = potion.getProduct().getRecipe();
		if (herbloreLevel > 0 && herbloreLevel < fin.getLevel())
		{
			return 0;
		}
		Map<Node, Integer> base = new IdentityHashMap<>();
		long sum = 1;
		for (Node n : ingredients(potion))
		{
			int have = Math.min(n.count(counts), MAX_UNITS);
			base.put(n, have);
			sum += (long) have * 3;
		}
		return maxCrafts(fin, base, herbloreLevel, true, (int) Math.min(sum, MAX_UNITS * 3L));
	}

	private static String qty(Node n, int amount)
	{
		String qty = String.format(Locale.US, "%,d", amount);
		return n.isDosed() ? qty + " doses of " + Catalog.lower(n.getName()) : qty + " " + Catalog.lower(n.getName());
	}

	private static int maxCrafts(Recipe fin, Map<Node, Integer> base, int lvl, boolean allowCraft, int bound)
	{
		int lo = 0;
		int hi = bound;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			Ctx c = new Ctx(base, lvl, allowCraft);
			c.makeFinal(fin, mid);
			if (c.shortfalls.isEmpty())
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return lo;
	}

	/** Most final crafts this one input could supply, ignoring the others. */
	private static int maxForInput(Recipe.Input in, Map<Node, Integer> base, int lvl, int bound)
	{
		int lo = 0;
		int hi = bound;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			Ctx c = new Ctx(base, lvl, true);
			c.need(in.getNode(), in.getQty() * mid);
			if (c.shortfalls.isEmpty())
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return lo;
	}

	/** One simulated attempt: a private copy of the pool, consumed greedily. */
	private static final class Ctx
	{
		final Map<Node, Integer> pool;
		final int lvl;
		final boolean allowCraft;
		final Map<Recipe, Integer> crafts = new LinkedHashMap<>();
		Map<Node, Integer> shortfalls = new LinkedHashMap<>();
		/** Leaf shortages behind a short intermediate potion. */
		final Map<Node, Map<Node, Integer>> groups = new LinkedHashMap<>();
		final Set<String> blocked = new LinkedHashSet<>();

		Ctx(Map<Node, Integer> base, int lvl, boolean allowCraft)
		{
			this.pool = new IdentityHashMap<>(base);
			this.lvl = lvl;
			this.allowCraft = allowCraft;
		}

		void makeFinal(Recipe fin, int n)
		{
			if (n <= 0)
			{
				return;
			}
			for (Recipe.Input in : fin.getInputs())
			{
				need(in.getNode(), in.getQty() * n);
			}
			crafts.merge(fin, n, Integer::sum);
		}

		void need(Node node, int amount)
		{
			int have = pool.getOrDefault(node, 0);
			int take = Math.min(have, amount);
			pool.put(node, have - take);
			int rem = amount - take;
			if (rem == 0)
			{
				return;
			}

			Recipe r = node.getRecipe();
			if (r == null || !allowCraft)
			{
				short_(node, rem);
				return;
			}

			if (lvl > 0 && lvl < r.getLevel())
			{
				blocked.add(capital(r) + ": " + r.getLevel() + " Herblore");
				short_(node, rem);
				return;
			}

			if (r.isAltForm())
			{
				// Cleaning / crushing: limited by the raw form you hold.
				Recipe.Input src = r.getInputs().get(0);
				int crafts = ceilDiv(rem, r.getYield());
				int srcHave = pool.getOrDefault(src.getNode(), 0);
				int can = Math.min(crafts, srcHave / src.getQty());
				if (can > 0 && r.getTool() != null && pool.getOrDefault(r.getTool(), 0) <= 0)
				{
					blocked.add("No " + Catalog.lower(r.getTool().getName()));
					can = 0;
				}
				if (can > 0)
				{
					pool.put(src.getNode(), srcHave - can * src.getQty());
					this.crafts.merge(r, can, Integer::sum);
					int produced = can * r.getYield();
					int used = Math.min(produced, rem);
					pool.merge(node, produced - used, Integer::sum);
					rem -= used;
				}
				if (rem > 0)
				{
					short_(node, rem);
				}
				return;
			}

			int crafts = ceilDiv(rem, r.getYield());
			// Shortages inside an intermediate potion's chain are grouped
			// under that potion, so super combat reads "for super defence:
			// short 10 cadantine" instead of a flat list of leaves.
			Map<Node, Integer> outer = shortfalls;
			Map<Node, Integer> inner = node.isDosed() ? new LinkedHashMap<>() : outer;
			shortfalls = inner;
			for (Recipe.Input in : r.getInputs())
			{
				need(in.getNode(), in.getQty() * crafts);
			}
			shortfalls = outer;
			if (inner != outer && !inner.isEmpty())
			{
				short_(node, rem);
				groups.computeIfAbsent(node, k -> new LinkedHashMap<>()).putAll(inner);
			}
			this.crafts.merge(r, crafts, Integer::sum);
			pool.merge(node, crafts * r.getYield() - rem, Integer::sum);
		}

		private void short_(Node node, int qty)
		{
			shortfalls.merge(node, qty, Integer::sum);
		}

		private static String capital(Recipe r)
		{
			// "Clean %d grimy torstol" -> "Cleaning grimy torstol"
			String s = r.getStepFormat().replace("%d ", "");
			int sp = s.indexOf(' ');
			String verb = sp < 0 ? s : s.substring(0, sp);
			String rest = sp < 0 ? "" : s.substring(sp);
			switch (verb)
			{
				case "Clean":
					return "Cleaning" + rest;
				case "Make":
					return "Making" + rest;
				case "Crush":
					return "Crushing" + rest;
				case "Mix":
					return "Mixing" + rest;
				default:
					return s;
			}
		}

		private static int ceilDiv(int a, int b)
		{
			return (a + b - 1) / b;
		}
	}
}

package com.potionprep;

