package com.potionprep;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.Map;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JToggleButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.QuantityFormatter;

class PotionPrepPanel extends PluginPanel
{
	private static final Color GOOD = new Color(0x5FBF5F);
	private static final Color ACTION = new Color(0xFFB000);
	private static final Color BAD = new Color(0xE05A5A);

	private final PotionPrepPlugin plugin;
	private final ItemManager itemManager;

	private final IconTextField search = new IconTextField();
	private final PotionGrid grid;
	private final JLabel selectedLabel = new JLabel();
	private final JLabel makeableLabel = new JLabel();
	private final JLabel makeableSub = new JLabel();
	private final JPanel rowsPanel = new JPanel();
	private final JPanel stepsPanel = new JPanel();
	private final JLabel statusLabel = new JLabel();
	private final JToggleButton showToggle = new JToggleButton("Show in bank");

	PotionPrepPanel(PotionPrepPlugin plugin, ItemManager itemManager)
	{
		// Wrapped: RuneLite puts the panel in a vertical scroll pane at the
		// standard sidebar size, so a long panel scrolls instead of forcing
		// the client window taller.
		super(true);
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.grid = new PotionGrid(itemManager, plugin::selectFromPanel);

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 30));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.setToolTipText("Search potions");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				grid.setFilter(search.getText());
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				grid.setFilter(search.getText());
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				grid.setFilter(search.getText());
			}
		});
		search.addActionListener(e ->
		{
			Potion first = grid.firstVisible();
			if (first != null)
			{
				plugin.selectFromPanel(first);
			}
		});
		search.addClearListener(() -> grid.setFilter(""));
		content.add(stretch(search));
		content.add(Box.createVerticalStrut(6));

		content.add(stretch(grid));
		content.add(Box.createVerticalStrut(10));

		JPanel summary = new JPanel();
		summary.setLayout(new BoxLayout(summary, BoxLayout.Y_AXIS));
		summary.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		summary.setBorder(new EmptyBorder(6, 8, 6, 8));
		JPanel top = new JPanel(new BorderLayout(6, 0));
		top.setOpaque(false);
		selectedLabel.setFont(FontManager.getRunescapeBoldFont());
		selectedLabel.setForeground(Color.WHITE);
		makeableLabel.setFont(FontManager.getRunescapeBoldFont());
		top.add(selectedLabel, BorderLayout.CENTER);
		top.add(makeableLabel, BorderLayout.EAST);
		top.setAlignmentX(LEFT_ALIGNMENT);
		summary.add(top);
		makeableSub.setFont(FontManager.getRunescapeSmallFont());
		makeableSub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		summary.add(left(makeableSub));
		content.add(stretch(summary));
		content.add(Box.createVerticalStrut(6));

		showToggle.setFocusable(false);
		showToggle.setToolTipText("While on, the bank opens filtered to this potion");
		showToggle.addActionListener(e -> plugin.setShowInBank(showToggle.isSelected()));
		content.add(stretch(showToggle));
		content.add(Box.createVerticalStrut(10));

		content.add(left(heading("Ingredients")));
		rowsPanel.setLayout(new BoxLayout(rowsPanel, BoxLayout.Y_AXIS));
		rowsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(stretch(rowsPanel));
		content.add(Box.createVerticalStrut(10));

		content.add(left(heading("To do")));
		stepsPanel.setLayout(new BoxLayout(stepsPanel, BoxLayout.Y_AXIS));
		stepsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.add(stretch(stepsPanel));
		content.add(Box.createVerticalStrut(10));

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		content.add(left(statusLabel));

		add(content, BorderLayout.NORTH);
	}

	void update(PotionPlan plan, String status, Map<Potion, Integer> makeable, int herbloreLevel, boolean showingInBank)
	{
		showToggle.setSelected(showingInBank);
		grid.setSelected(plan.getPotion());
		grid.setStats(makeable, herbloreLevel);
		Potion potion = plan.getPotion();
		int n = potion.toPotions(plan.getMakeable());
		int now = potion.toPotions(plan.getMakeableNow());
		selectedLabel.setText(potion.potionName());
		selectedLabel.setToolTipText("Level " + potion.getLevel());
		makeableLabel.setText(QuantityFormatter.formatNumber(n));
		makeableLabel.setForeground(n > 0 ? GOOD : BAD);
		makeableLabel.setToolTipText("Potions you can make");
		makeableSub.setText(n == 0 ? "None makeable"
			: now == n ? "All ready"
			: QuantityFormatter.formatNumber(now) + " ready &middot; +" + QuantityFormatter.formatNumber(n - now) + " after prep");
		makeableSub.setText(wrap(makeableSub.getText()));

		rowsPanel.removeAll();
		for (PotionPlan.Row row : plan.getRows())
		{
			rowsPanel.add(ingredientRow(row));
			rowsPanel.add(Box.createVerticalStrut(2));
		}

		stepsPanel.removeAll();
		for (PotionPlan.Step step : plan.getSteps())
		{
			JLabel l = new JLabel(wrap(bullet(step.getSeverity()) + step.getText()));
			l.setFont(FontManager.getRunescapeSmallFont());
			l.setForeground(color(step.getSeverity()));
			l.setBorder(new EmptyBorder(2, 0, 2, 0));
			l.setToolTipText(step.getHint());
			stepsPanel.add(left(l));
		}

		statusLabel.setText(wrap(status));
		revalidate();
		repaint();
	}

	private JPanel ingredientRow(PotionPlan.Row row)
	{
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(2, 4, 2, 8));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		itemManager.getImage(row.getItemId()).addTo(icon);
		p.add(icon, BorderLayout.WEST);

		JLabel name = new JLabel(row.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(row.getHave() > 0 ? Color.WHITE : ColorScheme.MEDIUM_GRAY_COLOR);
		p.add(name, BorderLayout.CENTER);

		JLabel qty = new JLabel(QuantityFormatter.quantityToStackSize(row.getHave()) + (row.isDoses() ? " doses" : ""));
		if (row.isDoses())
		{
			qty.setToolTipText("All doses (1) to (4) combined");
		}
		qty.setFont(FontManager.getRunescapeSmallFont());
		qty.setForeground(row.getHave() > 0 ? GOOD : ColorScheme.MEDIUM_GRAY_COLOR);
		p.add(qty, BorderLayout.EAST);
		return p;
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return l;
	}

	private static String bullet(PotionPlan.Severity s)
	{
		switch (s)
		{
			case WARNING:
				// Plain ASCII: the RuneScape font has no bullet glyphs.
				return "! ";
			default:
				return "";
		}
	}

	private static Color color(PotionPlan.Severity s)
	{
		switch (s)
		{
			case WARNING:
				return BAD;
			default:
				return ACTION;
		}
	}

	private static String wrap(String text)
	{
		return "<html><body style='width:165px'>" + text + "</body></html>";
	}

	private static JPanel left(java.awt.Component c)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(c, BorderLayout.WEST);
		p.setAlignmentX(LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height + 400));
		return p;
	}

	private static JPanel stretch(java.awt.Component c)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(c, BorderLayout.CENTER);
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}
}

package com.potionprep;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ScriptID;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/**
 * Filters the bank to one potion's ingredients and lines them up in a single
 * column, using the core Bank Tags plugin's tag + layout API. Nothing is
 * moved server-side: the layout is purely how the client draws the bank.
 */
@Slf4j
@PluginDescriptor(
	name = "Potion Prep",
	description = "Filter the bank to a potion's ingredients and see what you need to clean, crush or gather",
	tags = {"herblore", "potion", "bank", "herb", "secondary"}
)
@PluginDependency(BankTagsPlugin.class)
public class PotionPrepPlugin extends Plugin
{
	static final String TAG = "potion prep";
	private static final int BANK_COLUMNS = 8;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ConfigManager configManager;
	@Inject private ItemManager itemManager;
	@Inject private PotionPrepConfig config;
	@Inject private TagManager tagManager;
	@Inject private LayoutManager layoutManager;
	@Inject private BankTagsService bankTagsService;

	private PotionPrepPanel panel;
	private NavigationButton navButton;

	private Potion selected;
	private final Set<Integer> trackedIds = new HashSet<>();

	// Last observed bank. Null means "not seen this session", which is different from empty.
	private Map<Integer, Integer> bankCounts;
	private long bankObservedAt;
	private final Map<Integer, Integer> storageCounts = new HashMap<>();
	private final Map<Integer, Integer> invCounts = new HashMap<>();
	private int herbloreLevel;

	@Provides
	PotionPrepConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PotionPrepConfig.class);
	}

	@Override
	protected void startUp()
	{
		tagManager.registerTag(TAG, itemId -> trackedIds.contains(itemId));

		panel = new PotionPrepPanel(this, itemManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Potion Prep")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		Potion saved = parse(config.potion());
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				herbloreLevel = client.getRealSkillLevel(Skill.HERBLORE);
				readInventory(client.getItemContainer(InventoryID.INV));
				readBank(client.getItemContainer(InventoryID.BANK));
			}
			select(saved != null ? saved : Potion.PRAYER, false);
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			if (TAG.equals(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
			tagManager.unregisterTag(TAG);
			layoutManager.removeLayout(TAG);
		});
		clientToolbar.removeNavigation(navButton);
		panel = null;
		selected = null;
		bankCounts = null;
		storageCounts.clear();
		invCounts.clear();
	}

	// --- Called from the panel (EDT) ---

	void selectFromPanel(Potion potion)
	{
		clientThread.invokeLater(() -> select(potion, true));
	}

	/**
	 * The panel's "Show in bank" toggle. While on, every bank opened shows
	 * the selected potion's layout; turning it off restores the normal bank.
	 */
	void setShowInBank(boolean on)
	{
		configManager.setConfiguration(PotionPrepConfig.GROUP, "showInBank", on);
		clientThread.invokeLater(() ->
		{
			if (on && isBankOpen())
			{
				openTag();
			}
			else if (!on && TAG.equals(bankTagsService.getActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
			pushToPanel(null);
		});
	}

	// --- Client thread ---

	private void select(Potion potion, boolean persist)
	{
		selected = potion;
		trackedIds.clear();
		trackedIds.addAll(PotionPlan.layoutItems(potion));
		if (persist)
		{
			configManager.setConfiguration(PotionPrepConfig.GROUP, "potion", potion.name());
		}
		saveLayout();
		if (TAG.equals(bankTagsService.getActiveTag()) && isBankOpen())
		{
			openTag();
		}
		pushToPanel(null);
	}

	private void saveLayout()
	{
		if (selected == null)
		{
			return;
		}
		int col = Math.max(1, Math.min(BANK_COLUMNS, config.column())) - 1;
		List<int[]> rows = PotionPlan.layoutRows(selected);
		Layout layout = new Layout(TAG);
		for (int row = 0; row < rows.size(); row++)
		{
			int[] ids = rows.get(row);
			// Each action row ends at the chosen column and runs leftwards,
			// or rightwards when there isn't room on the left.
			int start = Math.max(0, Math.min(col - (ids.length - 1), BANK_COLUMNS - ids.length));
			for (int i = 0; i < ids.length; i++)
			{
				layout.setItemAtPos(ids[i], row * BANK_COLUMNS + start + i);
			}
		}
		layoutManager.saveLayout(layout);
	}

	private void openTag()
	{
		// No OPTION_ALLOW_MODIFICATIONS: dragging items in this view must not
		// rewrite the layout we generate.
		bankTagsService.openBankTag(TAG, 0);
	}

	private boolean isBankOpen()
	{
		Widget w = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return w != null && !w.isHidden();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && config.showInBank() && selected != null)
		{
			// Let the bank finish building before switching tab.
			clientThread.invokeLater(this::openTag);
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING || !TAG.equals(bankTagsService.getActiveTag()))
		{
			return;
		}

		// Unf potions and vials of water can sit in potion storage, which is
		// not part of the bank item container. The Bank Tags layout draws
		// them with their real quantity, so read it back off the widgets.
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null)
		{
			return;
		}
		Map<Integer, Integer> seen = new HashMap<>();
		Widget[] children = items.getChildren();
		if (children != null)
		{
			for (Widget c : children)
			{
				// Layout placeholders (items you don't have) are drawn faded with
				// quantity Integer.MAX_VALUE, so skip anything faded.
				if (c == null || c.isHidden() || c.getOpacity() > 0 || c.getItemQuantity() == Integer.MAX_VALUE
					|| !trackedIds.contains(c.getItemId()))
				{
					continue;
				}
				seen.merge(c.getItemId(), c.getItemQuantity(), Math::max);
			}
		}
		// The layout shows the bank quantity when there is one, otherwise the
		// potion storage quantity. Keep only the storage-only ones so they can
		// be added to the bank counts without double counting.
		storageCounts.clear();
		seen.forEach((id, qty) ->
		{
			if (qty > 0 && (bankCounts == null || !bankCounts.containsKey(id)))
			{
				storageCounts.put(id, qty);
			}
		});
		pushToPanel(null);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			readBank(event.getItemContainer());
			pushToPanel(null);
		}
		else if (event.getContainerId() == InventoryID.INV)
		{
			readInventory(event.getItemContainer());
			pushToPanel(null);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.HERBLORE && event.getLevel() != herbloreLevel)
		{
			herbloreLevel = event.getLevel();
			pushToPanel(null);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			if (event.getGameState() == GameState.LOGIN_SCREEN)
			{
				// Different account may log in next.
				bankCounts = null;
				storageCounts.clear();
				herbloreLevel = 0;
			}
			invCounts.clear();
			pushToPanel(null);
		}
		else if (event.getGameState() == GameState.LOGGED_IN && herbloreLevel == 0)
		{
			clientThread.invokeLater(() ->
			{
				herbloreLevel = client.getRealSkillLevel(Skill.HERBLORE);
				pushToPanel(null);
			});
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PotionPrepConfig.GROUP.equals(event.getGroup()) && "column".equals(event.getKey()))
		{
			clientThread.invokeLater(() ->
			{
				saveLayout();
				if (TAG.equals(bankTagsService.getActiveTag()) && isBankOpen())
				{
					openTag();
				}
			});
		}
	}

	private void readBank(ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		bankCounts = count(container);
		bankObservedAt = System.currentTimeMillis();
	}

	private void readInventory(ItemContainer container)
	{
		invCounts.clear();
		if (container != null)
		{
			invCounts.putAll(count(container));
		}
	}

	private static Map<Integer, Integer> count(ItemContainer container)
	{
		Map<Integer, Integer> out = new HashMap<>();
		for (Item item : container.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				out.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return out;
	}

	private Map<Integer, Integer> combinedCounts()
	{
		Map<Integer, Integer> all = new HashMap<>();
		if (bankCounts != null)
		{
			all.putAll(bankCounts);
		}
		storageCounts.forEach((id, qty) -> all.merge(id, qty, Integer::sum));
		invCounts.forEach((id, qty) -> all.merge(id, qty, Integer::sum));
		return all;
	}

	private void pushToPanel(String notice)
	{
		if (panel == null || selected == null)
		{
			return;
		}
		Map<Integer, Integer> counts = combinedCounts();
		PotionPlan plan = PotionPlan.compute(selected, counts, herbloreLevel);
		Map<Potion, Integer> makeable = new EnumMap<>(Potion.class);
		for (Potion p : Potion.values())
		{
			makeable.put(p, PotionPlan.makeable(p, counts, herbloreLevel));
		}
		int lvl = herbloreLevel;
		String status = notice != null ? notice
			: bankCounts == null ? "Open your bank to scan it"
			: "Bank seen " + ago(bankObservedAt);
		PotionPrepPanel p = panel;
		boolean showing = config.showInBank();
		SwingUtilities.invokeLater(() -> p.update(plan, status, makeable, lvl, showing));
	}

	private static String ago(long at)
	{
		long s = (System.currentTimeMillis() - at) / 1000;
		if (s < 60)
		{
			return "just now";
		}
		long m = s / 60;
		return m < 60 ? m + " min ago" : (m / 60) + " h ago";
	}

	private static Potion parse(String name)
	{
		try
		{
			return name == null || name.isEmpty() ? null : Potion.valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.potionprep;

import java.util.Arrays;
import java.util.List;
import lombok.Getter;
import lombok.Value;

/** One crafting action: inputs (+ optional tool) to {@link #yield} units of a product. */
@Getter
public final class Recipe
{
	@Value
	public static class Input
	{
		Node node;
		int qty;
	}

	private final int level;
	/**
	 * True when the product is just another form of the input (cleaning a
	 * herb, crushing a horn). Shortfalls are then reported on the product,
	 * "short 5 ranarr weed" rather than "short 5 grimy ranarr weed".
	 */
	private final boolean altForm;
	private final int yield;
	private final List<Input> inputs;
	private final Node tool;
	/** Step text; %d is the number of crafts. */
	private final String stepFormat;

	private Recipe(int level, boolean altForm, int yield, Node tool, String stepFormat, Input... inputs)
	{
		this.level = level;
		this.altForm = altForm;
		this.yield = yield;
		this.tool = tool;
		this.stepFormat = stepFormat;
		this.inputs = Arrays.asList(inputs);
	}

	static Input in(Node node, int qty)
	{
		return new Input(node, qty);
	}

	static Recipe clean(Node grimy, int level)
	{
		return new Recipe(level, true, 1, null, "Clean %d " + Catalog.lower(grimy.getName()), in(grimy, 1));
	}

	static Recipe crush(Node raw, int yield, Node pestle)
	{
		return new Recipe(1, true, yield, pestle, "Crush %d " + Catalog.lower(raw.getName()), in(raw, 1));
	}

	static Recipe mix(int level, int yield, String stepFormat, Input... inputs)
	{
		return new Recipe(level, false, yield, null, stepFormat, inputs);
	}
}

package com.potionprep;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class PotionPlanTest
{
	private static Map<Integer, Integer> counts(int... pairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put(pairs[i], pairs[i + 1]);
		}
		return m;
	}

	private static String steps(PotionPlan plan)
	{
		return plan.getSteps().stream().map(PotionPlan.Step::getText).collect(Collectors.joining(" | "));
	}

	@Test
	public void oneRowPerTaskWithInputsButNotOutput()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.SUPERANTIPOISON);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{ItemID.UNIDENTIFIED_IRIT}, rows.get(0));
		assertArrayEquals(new int[]{ItemID.IRIT_LEAF, ItemID.VIAL_WATER}, rows.get(1));
		assertArrayEquals(new int[]{ItemID.UNICORN_HORN, ItemID.PESTLE_AND_MORTAR}, rows.get(2));
		assertArrayEquals(new int[]{ItemID.IRITVIAL, ItemID.UNICORN_HORN_DUST}, rows.get(3));
	}

	@Test
	public void plainSecondaryHasNoTaskRowOfItsOwn()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.PRAYER);
		assertEquals(3, rows.size());
		assertArrayEquals(new int[]{ItemID.RANARRVIAL, ItemID.SNAPE_GRASS}, rows.get(2));
	}

	@Test
	public void staminaTasksChainThroughSuperEnergy()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.STAMINA);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{ItemID.AVANTOEVIAL, ItemID.MORTMYREMUSHROOM}, rows.get(2));
		assertArrayEquals(new int[]{ItemID._1DOSE2ENERGY, ItemID._2DOSE2ENERGY, ItemID._3DOSE2ENERGY, ItemID._4DOSE2ENERGY,
			ItemID.AMYLASE}, rows.get(3));
		assertFalse(PotionPlan.layoutItems(Potion.STAMINA).contains(ItemID._4DOSESTAMINA));
	}

	@Test
	public void rowsFitTheBankAndSkipTheFinishedPotion()
	{
		for (Potion p : Potion.values())
		{
			for (int[] row : PotionPlan.layoutRows(p))
			{
				assertTrue(p.name(), row.length >= 1 && row.length <= PotionPlan.BANK_COLUMNS);
			}
			for (int id : p.getProduct().rowIds())
			{
				assertFalse(p.name(), PotionPlan.layoutItems(p).contains(id));
			}
		}
	}

	@Test
	public void readyWhenUnfAndSecondaryInHand()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.RANARRVIAL, 14, ItemID.SNAPE_GRASS, 20), 99);
		assertEquals(14, plan.getMakeable());
		assertEquals(14, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Mix 14 prayer potions"));
		assertTrue(s, s.contains("Short 6 ranarr weed"));
	}

	@Test
	public void cleansAndMixesGrimyHerbs()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.UNIDENTIFIED_RANARR, 10, ItemID.RANARR_WEED, 4,
			ItemID.VIAL_WATER, 100, ItemID.SNAPE_GRASS, 100), 99);
		assertEquals(14, plan.getMakeable());
		assertEquals(0, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Clean 10 grimy ranarr weed"));
		assertTrue(s, s.contains("Make 14 ranarr (unf)"));
		assertTrue(s, s.contains("Short 86 ranarr weed"));
	}

	@Test
	public void vialsLimit()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.RANARR_WEED, 20, ItemID.VIAL_WATER, 5, ItemID.SNAPE_GRASS, 20), 99);
		assertEquals(5, plan.getMakeable());
		assertTrue(steps(plan), steps(plan).contains("Short 15 vial of water"));
	}

	@Test
	public void nonCrushableSecondaryNeverGetsACrushStep()
	{
		// The bug in the screenshot: super energy suggested crushing mort myre fungus.
		PotionPlan plan = PotionPlan.compute(Potion.SUPER_ENERGY, counts(ItemID.AVANTOEVIAL, 314, ItemID.MORTMYREMUSHROOM, 957,
			ItemID.AVANTOE, 110, ItemID.VIAL_WATER, 4240, ItemID.UNIDENTIFIED_AVANTOE, 2148), 99);
		assertEquals(957, plan.getMakeable());
		assertEquals(314, plan.getMakeableNow());
		String s = steps(plan);
		assertFalse(s, s.contains("Crush"));
		assertTrue(s, s.contains("Clean 533 grimy avantoe"));
		assertTrue(s, s.contains("Make 643 avantoe (unf)"));
		assertTrue(s, s.contains("Short 1,615 mort myre fungus"));
	}

	@Test
	public void hugeCountsDoNotOverflow()
	{
		PotionPlan plan = PotionPlan.compute(Potion.SUPER_ENERGY, counts(ItemID.AVANTOEVIAL, Integer.MAX_VALUE, ItemID.MORTMYREMUSHROOM, 10), 99);
		assertEquals(10, plan.getMakeable());
	}

	@Test
	public void crushesRawSecondaryOnlyWithPestle()
	{
		Map<Integer, Integer> c = counts(ItemID.LANTADYMEVIAL, 10, ItemID.BLUE_DRAGON_SCALE, 10);
		PotionPlan noPestle = PotionPlan.compute(Potion.ANTIFIRE, c, 99);
		assertEquals(0, noPestle.getMakeable());
		assertTrue(steps(noPestle), steps(noPestle).contains("No pestle and mortar"));

		c.put(ItemID.PESTLE_AND_MORTAR, 1);
		PotionPlan withPestle = PotionPlan.compute(Potion.ANTIFIRE, c, 99);
		assertEquals(10, withPestle.getMakeable());
		assertTrue(steps(withPestle), steps(withPestle).contains("Crush 10 blue dragon scale"));
	}

	@Test
	public void staminaChainsThroughSuperEnergy()
	{
		// 2 super energy(4) = 8 doses on hand, plus 2 unf + 2 fungus = 6 more doses.
		PotionPlan plan = PotionPlan.compute(Potion.STAMINA, counts(ItemID._4DOSE2ENERGY, 2, ItemID.AVANTOEVIAL, 2,
			ItemID.MORTMYREMUSHROOM, 2, ItemID.AMYLASE, 100), 99);
		assertEquals(3, Potion.STAMINA.toPotions(plan.getMakeable()));
		assertEquals("Stamina potion(4)", Potion.STAMINA.potionName());
		assertEquals("Prayer potion(3)", Potion.PRAYER.potionName());
		assertEquals(14, plan.getMakeable());
		assertEquals(8, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Mix 2 super energies"));
		assertTrue(s, s.contains("Add amylase to 14 doses"));
	}

